selector_to_html = {"a[href=\"#see-also\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">See Also<a class=\"headerlink\" href=\"#see-also\" title=\"Link to this heading\">#</a></h2>", "a[href=\"user_guide.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">User Guide<a class=\"headerlink\" href=\"#user-guide\" title=\"Link to this heading\">#</a></h1><p>For</p>", "a[href=\"#pc-fig-dff-caiman\"]": "<figure class=\"align-default\" id=\"pc-fig-dff-caiman\">\n<a class=\"reference internal image-reference\" href=\"_images/dff_baseline_strategies_caiman.png\"><img alt=\"CaImAn default DF/F strategy\" src=\"_images/dff_baseline_strategies_caiman.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\"><a class=\"reference external\" href=\"https://github.com/flatironinstitute/CaImAn\">CaImAn</a> uses a default baseline of the <code class=\"docutils literal notranslate\"><span class=\"pre\">lower</span> <span class=\"pre\">8th</span> <span class=\"pre\">percentile</span></code> and a moving window of <code class=\"docutils literal notranslate\"><span class=\"pre\">200</span> <span class=\"pre\">frames</span></code>.</span><a class=\"headerlink\" href=\"#pc-fig-dff-caiman\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#pc-fig-dff-oasis\"]": "<figure class=\"align-default\" id=\"pc-fig-dff-oasis\">\n<a class=\"reference internal image-reference\" href=\"_images/dff_oasis.png\"><img alt=\"_images/dff_oasis.png\" src=\"_images/dff_oasis.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\">Raw, neuropil, \u0394F/F\u2080 and resulting deconvolved spikes as output by <a class=\"reference external\" href=\"https://github.com/MouseLand/suite2p\">Suite2p</a>.</span><a class=\"headerlink\" href=\"#pc-fig-dff-oasis\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"processing_flow.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Processing Flow<a class=\"headerlink\" href=\"#processing-flow\" title=\"Link to this heading\">#</a></h1><p>High-level overview of all processing steps executed by <code class=\"docutils literal notranslate\"><span class=\"pre\">lsp.pipeline()</span></code>.</p>", "a[href=\"#f-f-calculation-methods\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u0394F/F Calculation Methods<a class=\"headerlink\" href=\"#f-f-calculation-methods\" title=\"Link to this heading\">#</a></h2><p>Different pipelines handle \u0394F/F\u2080 differently:</p>", "a[href=\"#suite2p\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Suite2p<a class=\"headerlink\" href=\"#suite2p\" title=\"Link to this heading\">#</a></h3><p>Suite2p does <strong>not</strong> output traces in \u0394F/F\u2080 format directly. Instead, it gives you the raw trace and the neuropil, along with spike estimates if you ran deconvolution. The neuropil represents fluorescence from the surrounding non-somatic tissue. As an optional step, many experimenters apply a fixed subtraction:</p>", "a[href=\"#extract\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">EXTRACT<a class=\"headerlink\" href=\"#extract\" title=\"Link to this heading\">#</a></h3><p><a class=\"reference external\" href=\"https://github.com/schnitzer-lab/EXTRACT-public\">EXTRACT</a> outputs raw fluorescence signals without built-in \u0394F/F\u2080 calculation. You compute it yourself using something like a low-percentile (e.g. 10%) as F\u2080. Most users apply a global or sliding percentile window.</p><p><strong>Neuropil:</strong> Handled implicitly. The algorithm uses robust factorization to ignore background and neuropil. There\u2019s no explicit subtraction or coefficient to tune\u2014it isolates only what fits a consistent spatial footprint and suppresses outliers by design.</p>", "a[href=\"#pipeline-comparison\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Pipeline Comparison<a class=\"headerlink\" href=\"#pipeline-comparison\" title=\"Link to this heading\">#</a></h1><p>This page compares how different calcium imaging analysis pipelines handle \u0394F/F calculation, neuropil correction, and spike deconvolution.</p>", "a[href=\"postprocessing.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Postprocessing Functions<a class=\"headerlink\" href=\"#postprocessing-functions\" title=\"Link to this heading\">#</a></h1><p>This guide covers the postprocessing functions available in LBM-Suite2p-Python for analyzing and refining calcium imaging traces after Suite2p extraction.</p>", "a[href=\"#caiman\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">CaImAn<a class=\"headerlink\" href=\"#caiman\" title=\"Link to this heading\">#</a></h3><p>CaImAn computes \u0394F/F\u2080 using a <strong>running low-percentile baseline</strong>. By default, it uses the <strong>8th percentile</strong> over a <strong>500 frame</strong> window. The idea is to track the lower envelope of the signal to get F\u2080 without being biased by transients.</p><p><strong>Neuropil/background:</strong> CaImAn handles this as part of its CNMF model. Background and neuropil are explicitly separated into distinct spatial/temporal components, so the output traces are background subtracted during this factorization.</p>", "a[href=\"#deconvolution-algorithms\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Deconvolution Algorithms<a class=\"headerlink\" href=\"#deconvolution-algorithms\" title=\"Link to this heading\">#</a></h2><p>Different pipelines use different approaches to spike deconvolution, each with their own \u03c4 (tau) handling:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
